package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("results").Parse(`
<html><body>
<h2>Product Search</h2>
<form method="GET" action="/search">
  <input name="category" value="{{.Query}}">
  <button>Search</button>
</form>
<table>
{{range .Products}}
<tr><td>{{.Name}}</td><td>${{.Price}}</td><td>{{.Description}}</td></tr>
{{end}}
</table>
</body></html>`))
}

type Product struct {
	Name        string
	Price       string
	Description string
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")

	// Basic input length check
	if len(category) > 100 {
		http.Error(w, "Input too long", http.StatusBadRequest)
		return
	}

	// Reject obvious null bytes
	if strings.Contains(category, "\x00") {
		http.Error(w, "Invalid input", http.StatusBadRequest)
		return
	}

	// Build query - developer note: category is from a controlled dropdown in the UI
	query := fmt.Sprintf(
		"SELECT name, price::text, description FROM products WHERE category = '%s' AND active = true ORDER BY name LIMIT 50",
		category,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search unavailable", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.Name, &p.Price, &p.Description); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, struct {
		Query    string
		Products []Product
	}{category, products})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
